@-moz-document domain("roblox.com") {
/* IN ORDER TO CHANGE THE PROFILE PICTURE U NEED TO HAVE A 200X200 PIXELS 
  PHOTO AND U NEED TO HAVE THE BAS64 CODE FOR IT, U CAN GET THAT FROM 
  https://www.base64-image.de/ ONCE U HAVE THE BASE64 CODE PASTE IT IN THE
  LINE 19 IN () WHERE IT SAYS 
  background-image: url("data:image/jpeg;base64,ACTUAL_BASE64_GOES_HERE") !important;
  THE BASE64 CODE STARTS WITH THE
  url(data:image/jpeg;base64,ACTUAL_BASE64_HERE") so u need to delete that 
  part and paste ur base64 i also suggest to add ur profile link as a URL 
  instead of the main roblox link as a WEB so the pfp could only appear on ur profile
  if u still have issues then feel free to dm me on dc: pllexii */

  .user-profile-header-details-avatar-container .thumbnail-2d-container,
  .user-profile-header-details-avatar-container .avatar-card-image {
    position: relative !important;
  }

  .user-profile-header-details-avatar-container .thumbnail-2d-container img,
  .user-profile-header-details-avatar-container .avatar-card-image img {
    visibility: hidden !important;
  }

  .user-profile-header-details-avatar-container .thumbnail-2d-container::after,
  .user-profile-header-details-avatar-container .avatar-card-image::after {
    content: "" !important;
    position: absolute !important;
    inset: 0 !important;
    visibility: visible !important;
    background-image: url("data:image/jpeg;base64,ACTUAL_BASE64_GOES_HERE") !important;
    background-size: cover !important;
    background-position: center !important;
    border-radius: 50% !important;
  }
}
